t;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#CREUSEMENT&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;Creusement&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#EVENTRATION&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;&#201;ventration&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#MALEFICE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;Mal&#233;fice&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#PISTAGE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;Pistage&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#SANTEDIVINE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;Sant&#233; divine&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#VISIONNOCTURNE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;Vision nocturne&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#BOND&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;Bond&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#CROCENJAMBE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;Croc-en-jambe&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#FEROCITE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;F&#233;rocit&#233;&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#MOBILITE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;Mobilit&#233;&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#PIETINEMENT&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;Pi&#233;tinement&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#SENSDESPIEGES&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;Sens des pi&#232;ges&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#VOL&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;Vol&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#CANALISATIONDENERGIENEGATIVE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;Canalisation d’&#233;nergie n&#233;gative&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#DECOUVERTE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;D&#233;couverte&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#FORMEANIMALE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;Forme animale&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#MONTURE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;Monture&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#POISON&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;Poison&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#SENSIBILITEALALUMIERE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;Sensibilit&#233; &#224; la lumi&#232;re&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#VORTEX&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;Vortex&lt;/a&gt;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#CANALISATIONDENERGIEPOSITIVE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;Canalisation d’&#233;nergie positive&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#DEFENSEIMPORTANTE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;D&#233;fense importante&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#GRACE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;Gr&#226;ce&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#MORTVIVANT&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;Mort-vivant&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#PREPARATIONDEPOTION&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;Pr&#233;paration de potion&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#SOUFFLE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;Souffle&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&amp;emsp;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#CANNIBALISME&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;Cannibalisme&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#DEFI&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;D&#233;fi&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#GUERISONACCELEREE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;Gu&#233;rison acc&#233;l&#233;r&#233;e&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#NAGEDANSLATERRE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;Nage dans la terre&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#PROTECTIONDALLIE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;Protection d’alli&#233;&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&amp;emsp;&lt;/td&gt;&lt;td&gt;&amp;emsp;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;table width=&quot;100%&quot;&gt;&lt;tr&gt;&lt;td width=&quot;49%&quot;&gt;
&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;ABSORPTIONDENERGIE&quot; href=&quot;#ABSORPTIONDENERGIE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Absorption d’&#233;nergie.&lt;/b&gt; Si l’arm&#233;e blesse un ennemi, elle r&#233;duit le &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#MA&quot; title=&quot;Le combat de masse&quot;&gt;MA&lt;/a&gt; et la &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#VDEF&quot; title=&quot;Le combat de masse&quot;&gt;VD&#233;f&lt;/a&gt; de celui-ci de 1 pendant 24 heures.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;ALCHIMIE&quot; href=&quot;#ALCHIMIE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Alchimie (&lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;alchimiste&lt;/a&gt; 1).&lt;/b&gt; Une fois par bataille, l’arm&#233;e peut se soigner comme si elle disposait de la ressource &lt;a class=&quot;pagelink&quot; href=&quot;Ressources-Des-Arm&#233;es-(Guerre).html#POTIONSDESOINS&quot; title=&quot;Les ressources des arm&#233;es&quot;&gt;potions de soins&lt;/a&gt;. Cela ne co&#251;te aucun &lt;a class=&quot;pagelink&quot; href=&quot;Royaumes-Et-Guerre.html#POINTSDECONSTRUCTION&quot; title=&quot;Les royaumes et la guerre&quot;&gt;PC&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;AFFAIBLISSEMENTTEMPORAIREDIMINUTIONPERMANENTEDECARACTERISTIQUE&quot; href=&quot;#AFFAIBLISSEMENTTEMPORAIREDIMINUTIONPERMANENTEDECARACTERISTIQUE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Affaiblissement temporaire/diminution permanente de caract&#233;ristique.&lt;/b&gt; Ce pouvoir fonctionne comme &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#SAIGNEMENT&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;saignement&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;AMPHIBIE&quot; href=&quot;#AMPHIBIE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Amphibie.&lt;/b&gt; L’arm&#233;e peut traverser des &#233;tendues d’eau ou se d&#233;placer dans l’eau et ignore les valeurs de &lt;a class=&quot;pagelink&quot; href=&quot;Communaut&#233;s-Et-Quartiers.html#DEFENSE&quot; title=&quot;Les communaut&#233;s et les quartiers&quot;&gt;D&#233;fense&lt;/a&gt; li&#233;es aux obstacles aqueux.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;AQUATIQUE&quot; href=&quot;#AQUATIQUE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Aquatique.&lt;/b&gt; L’arm&#233;e augmente son &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#MA&quot; title=&quot;Le combat de masse&quot;&gt;MA&lt;/a&gt; et sa &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#VDEF&quot; title=&quot;Le combat de masse&quot;&gt;VD&#233;f&lt;/a&gt; de 1 contre les arm&#233;es qui se trouvent sur l’eau ou sur un navire. En revanche, son MA diminue de 2 contre une arm&#233;e qui se trouve sur terre (&#224; moins que l’arm&#233;e aquatique ne poss&#232;de aussi le pouvoir &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#AMPHIBIE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;amphibie&lt;/a&gt;, auquel cas elle ne subit aucun malus au MA).&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;ATTAQUESOURNOISE&quot; href=&quot;#ATTAQUESOURNOISE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Attaque sournoise (&lt;a class=&quot;pagelink&quot; href=&quot;Roublard.html&quot; title=&quot;Le roublard&quot;&gt;roublard&lt;/a&gt; 1).&lt;/b&gt; L’arm&#233;e augmente son &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#MA&quot; title=&quot;Le combat de masse&quot;&gt;MA&lt;/a&gt; de 1 quand elle tend une &lt;a class=&quot;pagelink&quot; href=&quot;Tactiques-Des-Arm&#233;es-(Guerre).html#EMBUSCADE&quot; title=&quot;Les tactiques des arm&#233;es&quot;&gt;embuscade&lt;/a&gt;, quand elle utilise la tactique &lt;a class=&quot;pagelink&quot; href=&quot;Tactiques-Des-Arm&#233;es-(Guerre).html#SPECIALISTESDELENCERCLEMENT&quot; title=&quot;Les tactiques des arm&#233;es&quot;&gt;sp&#233;cialistes de l’encerclement&lt;/a&gt; ou lors de la phase qui suit la tactique &lt;a class=&quot;pagelink&quot; href=&quot;Tactiques-Des-Arm&#233;es-(Guerre).html#FAUSSERETRAITE&quot; title=&quot;Les tactiques des arm&#233;es&quot;&gt;fausse retraite&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;AURADEBRAVOURE&quot; href=&quot;#AURADEBRAVOURE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Aura de bravoure (&lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html&quot; title=&quot;Le paladin&quot;&gt;paladin&lt;/a&gt; 3).&lt;/b&gt; L’arm&#233;e est immunis&#233;e contre les effets de terreur et r&#233;ussit automatiquement ses tests de &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#MORAL&quot; title=&quot;Le combat de masse&quot;&gt;moral&lt;/a&gt; pour &#233;viter la &lt;a class=&quot;pagelink&quot; href=&quot;Victoire-D&#233;route-Et-D&#233;faite-(Guerre).html&quot; title=&quot;Victoire, d&#233;route et d&#233;faite&quot;&gt;d&#233;route&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;AURASURNATURELLE&quot; href=&quot;#AURASURNATURELLE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Aura surnaturelle.&lt;/b&gt; Ce pouvoir fonctionne comme &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#TERREUR&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;terreur&lt;/a&gt; mais s’applique uniquement aux animaux (y compris aux montures animales).&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;AVEUGLEPARLALUMIERE&quot; href=&quot;#AVEUGLEPARLALUMIERE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Aveugl&#233; par la lumi&#232;re.&lt;/b&gt; Le &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#MA&quot; title=&quot;Le combat de masse&quot;&gt;MA&lt;/a&gt; et la &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#VDEF&quot; title=&quot;Le combat de masse&quot;&gt;VD&#233;f&lt;/a&gt; de l’arm&#233;e diminuent de 2 sous une vive lumi&#232;re.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;BOMBE&quot; href=&quot;#BOMBE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Bombe (&lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;alchimiste&lt;/a&gt; 1).&lt;/b&gt; Ce pouvoir fonctionne comme celui de &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#SOUFFLE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;souffle&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;BOND&quot; href=&quot;#BOND&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Bond.&lt;/b&gt; L’arm&#233;e augmente son &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#MA&quot; title=&quot;Le combat de masse&quot;&gt;MA&lt;/a&gt; de 1.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;CANALISATIONDENERGIENEGATIVE&quot; href=&quot;#CANALISATIONDENERGIENEGATIVE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Canalisation d’&#233;nergie n&#233;gative (&lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre.html&quot; title=&quot;Le pr&#234;tre&quot;&gt;pr&#234;tre&lt;/a&gt; 1).&lt;/b&gt; Lors de la phase de corps &#224; corps, l’arm&#233;e inflige +1d4 points de d&#233;g&#226;ts &#224; une arm&#233;e vivante choisie. Si l’arm&#233;e qui poss&#232;de ce pouvoir est compos&#233;e de &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#MORTVIVANT&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;morts-vivants&lt;/a&gt;, elle peut renoncer &#224; ces d&#233;g&#226;ts suppl&#233;mentaires pour se soigner : en subissant un malus au &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#MA&quot; title=&quot;Le combat de masse&quot;&gt;MA&lt;/a&gt; &#233;gal &#224; la moiti&#233; de son &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#FPA&quot; title=&quot;Le combat de masse&quot;&gt;FPA&lt;/a&gt; lors d’une phase &#224; distance ou au corps &#224; corps, elle peut gu&#233;rir d’un montant de &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#PV&quot; title=&quot;Le combat de masse&quot;&gt;points de vie&lt;/a&gt; &#233;gal &#224; son FPA.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;CANALISATIONDENERGIEPOSITIVE&quot; href=&quot;#CANALISATIONDENERGIEPOSITIVE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Canalisation d’&#233;nergie positive (&lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre.html&quot; title=&quot;Le pr&#234;tre&quot;&gt;pr&#234;tre&lt;/a&gt; 1, &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html&quot; title=&quot;Le paladin&quot;&gt;paladin&lt;/a&gt; 4).&lt;/b&gt; Lors de la phase de corps &#224; corps, l’arm&#233;e inflige +1d4 points de d&#233;g&#226;ts &#224; une arm&#233;e &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#MORTVIVANT&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;morte-vivante&lt;/a&gt; choisie. Elle peut renoncer &#224; ces d&#233;g&#226;ts suppl&#233;mentaires pour se soigner : en subissant un malus au &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#MA&quot; title=&quot;Le combat de masse&quot;&gt;MA&lt;/a&gt; &#233;gal &#224; la moiti&#233; de son &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#FPA&quot; title=&quot;Le combat de masse&quot;&gt;FPA&lt;/a&gt; lors d’une phase &#224; distance ou au corps &#224; corps, elle peut gu&#233;rir d’un montant de &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#PV&quot; title=&quot;Le combat de masse&quot;&gt;points de vie&lt;/a&gt; &#233;gal &#224; son FPA.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;CANNIBALISME&quot; href=&quot;#CANNIBALISME&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Cannibalisme.&lt;/b&gt; Chaque semaine o&#249; l’arm&#233;e remporte une bataille et peut se nourrir des cadavres, elle r&#233;duit sa &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#CONSOMMATION&quot; title=&quot;Le combat de masse&quot;&gt;Consommation&lt;/a&gt; de 1 (pour un minimum de 0).&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;CHARGEPUISSANTE&quot; href=&quot;#CHARGEPUISSANTE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Charge puissante.&lt;/b&gt; L’arm&#233;e augmente son &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#MA&quot; title=&quot;Le combat de masse&quot;&gt;MA&lt;/a&gt; de 1.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;CHATIMENTDUMAL&quot; href=&quot;#CHATIMENTDUMAL&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Ch&#226;timent du Mal (&lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html&quot; title=&quot;Le paladin&quot;&gt;paladin&lt;/a&gt; 1).&lt;/b&gt; Lors d’une unique phase de corps &#224; corps par bataille, l’arm&#233;e peut augmenter son &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#MA&quot; title=&quot;Le combat de masse&quot;&gt;MA&lt;/a&gt; de 2 contre une arm&#233;e Mauvaise. Si l’arm&#233;e vis&#233;e est compos&#233;e de &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#MORTVIVANT&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;morts-vivants&lt;/a&gt; ou d’ext&#233;rieurs Mauvais, le MA augmente de 4 au lieu de 2.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;COMBUSTION&quot; href=&quot;#COMBUSTION&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Combustion.&lt;/b&gt; Ce pouvoir fonctionne comme &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#SAIGNEMENT&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;saignement&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;COMPAGNONANIMAL&quot; href=&quot;#COMPAGNONANIMAL&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Compagnon animal (&lt;a class=&quot;pagelink&quot; href=&quot;Druide.html&quot; title=&quot;Le druide&quot;&gt;druide&lt;/a&gt; 1, &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html&quot; title=&quot;Le r&#244;deur&quot;&gt;r&#244;deur&lt;/a&gt; 4).&lt;/b&gt; Les compagnons animaux des soldats augmentent le &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#MA&quot; title=&quot;Le combat de masse&quot;&gt;MA&lt;/a&gt; de l’arm&#233;e de 1.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;COUPETOURDISSANT&quot; href=&quot;#COUPETOURDISSANT&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Coup &#233;tourdissant (&lt;a class=&quot;pagelink&quot; href=&quot;Moine.html&quot; title=&quot;Le moine&quot;&gt;moine&lt;/a&gt; 1).&lt;/b&gt; Ce pouvoir fonctionne comme &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#PARALYSIE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;paralysie&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;COURAGE&quot; href=&quot;#COURAGE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Courage (&lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html&quot; title=&quot;Le guerrier&quot;&gt;guerrier&lt;/a&gt; 2).&lt;/b&gt; Appliquez le bonus de courage des unit&#233;s aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#MORAL&quot; title=&quot;Le combat de masse&quot;&gt;moral&lt;/a&gt; contre la &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#TERREUR&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;terreur&lt;/a&gt; et la &lt;a class=&quot;pagelink&quot; href=&quot;Victoire-D&#233;route-Et-D&#233;faite-(Guerre).html&quot; title=&quot;Victoire, d&#233;route et d&#233;faite&quot;&gt;d&#233;route&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;CREATIONDETEMPETEDESABLE&quot; href=&quot;#CREATIONDETEMPETEDESABLE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Cr&#233;ation de temp&#234;te de sable.&lt;/b&gt; Une fois par bataille, l’arm&#233;e peut d&#233;cha&#238;ner une &lt;a class=&quot;pagelink&quot; href=&quot;Phases-Dune-Bataille-(Guerre).html#CONDITIONS&quot; title=&quot;Les phases d&amp;#39;une bataille&quot;&gt;temp&#234;te de sable&lt;/a&gt; sur le champ de bataille. La temp&#234;te fait rage jusqu’&#224; la fin de l’affrontement.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;CREATIONDEREJETON&quot; href=&quot;#CREATIONDEREJETON&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Cr&#233;ation de rejeton.&lt;/b&gt; Si cette arm&#233;e d&#233;truit une arm&#233;e vivante aussi grande qu’elle ou encore plus grande, elle peut r&#233;cup&#233;rer de suite un montant de &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#PV&quot; title=&quot;Le combat de masse&quot;&gt;pv&lt;/a&gt; &#233;gal &#224; deux fois son &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#FPA&quot; title=&quot;Le combat de masse&quot;&gt;FPA&lt;/a&gt; ou cr&#233;er une nouvelle arm&#233;e de m&#234;me type qu’elle mais de deux cat&#233;gories de taille de moins.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;CREATUREARTIFICIELLE&quot; href=&quot;#CREATUREARTIFICIELLE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Cr&#233;ature artificielle.&lt;/b&gt; L’arm&#233;e est immunis&#233;e contre la &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#MALADIE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;maladie&lt;/a&gt;, la &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#TERREUR&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;terreur&lt;/a&gt;, la &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#PARALYSIE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;paralysie&lt;/a&gt; et le &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#POISON&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;poison&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;CREUSEMENT&quot; href=&quot;#CREUSEMENT&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Creusement.&lt;/b&gt; L’arm&#233;e peut creuser sous une fortification (ou sous un &lt;a class=&quot;pagelink&quot; href=&quot;Communaut&#233;s-Et-Quartiers.html#MURDENCEINTE&quot; title=&quot;Les communaut&#233;s et les quartiers&quot;&gt;mur d’enceinte&lt;/a&gt;) si elle passe une phase &#224; distance ou au corps &#224; corps &#224; creuser. Lors des phases suivantes, elle ignore la &lt;a class=&quot;pagelink&quot; href=&quot;Communaut&#233;s-Et-Quartiers.html#DEFENSE&quot; title=&quot;Les communaut&#233;s et les quartiers&quot;&gt;D&#233;fense&lt;/a&gt; associ&#233;e &#224; cette fortification. Lors de la phase de creusement, l’arm&#233;e ne peut pas attaquer ni se faire attaquer, sauf si elle est oppos&#233;e &#224; une autre arm&#233;e qui utilise aussi creusement ou &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#NAGEDANSLATERRE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;nage dans la terre&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;CROCENJAMBE&quot; href=&quot;#CROCENJAMBE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Croc-en-jambe.&lt;/b&gt; &#192; chaque phase de corps &#224; corps, l’arm&#233;e ennemie voit sa &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#VDEF&quot; title=&quot;Le combat de masse&quot;&gt;VD&#233;f&lt;/a&gt; r&#233;duite de 1 jusqu’&#224; la fin de la phase.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;DECOUVERTE&quot; href=&quot;#DECOUVERTE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;D&#233;couverte (&lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;alchimiste&lt;/a&gt; 2).&lt;/b&gt; Ce pouvoir fonctionne comme &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#SAIGNEMENT&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;saignement&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;DEFENSEIMPORTANTE&quot; href=&quot;#DEFENSEIMPORTANTE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;D&#233;fense importante.&lt;/b&gt; L’arm&#233;e a une excellente d&#233;fense, comme une grosse r&#233;duction de d&#233;g&#226;ts ou de nombreuses immunit&#233;s et/ou r&#233;sistances. Augmentez sa &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#VDEF&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;VD&#233;f&lt;/a&gt; de 10 mais seulement contre les arm&#233;es incapables de franchir ces d&#233;fenses. Parfois, le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Maitredujeu.html&quot; title=&quot;MJ&quot;&gt;MJ&lt;/a&gt; sera simplement amen&#233; &#224; dire que l’arm&#233;e est invincible pour un ennemi donn&#233; car elle poss&#232;de des d&#233;fenses trop puissantes. (Cependant, le MJ ne devrait jamais opposer les &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Personnagejoueur.html&quot; title=&quot;PJ&quot;&gt;PJ&lt;/a&gt; &#224; un tel ennemi, &#224; moins que ce ne soient eux qui aient b&#234;tement lanc&#233; les hostilit&#233;s.)&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;DEFI&quot; href=&quot;#DEFI&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;D&#233;fi (&lt;a class=&quot;pagelink&quot; href=&quot;Chevalier.html&quot; title=&quot;Le chevalier&quot;&gt;chevalier&lt;/a&gt; 1).&lt;/b&gt; Une fois par bataille, l’arm&#233;e peut augmenter son &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#MA&quot; title=&quot;Le combat de masse&quot;&gt;MA&lt;/a&gt; de 2 contre une arm&#233;e donn&#233;e mais elle voit alors sa &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#VDEF&quot; title=&quot;Le combat de masse&quot;&gt;VD&#233;f&lt;/a&gt; diminuer de 1 contre les autres arm&#233;es. Ces effets persistent pendant toute la bataille.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;DELUGEDECOUPS&quot; href=&quot;#DELUGEDECOUPS&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;D&#233;luge de coups (&lt;a class=&quot;pagelink&quot; href=&quot;Moine.html&quot; title=&quot;Le moine&quot;&gt;moine&lt;/a&gt; 1).&lt;/b&gt; Le &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#MA&quot; title=&quot;Le combat de masse&quot;&gt;MA&lt;/a&gt; de l’arm&#233;e augmente de 1 lors de la premi&#232;re phase de corps &#224; corps. Pour toutes les suivantes, il augmente de 2 au lieu de 1.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;DEPOURVUDINTELLIGENCE&quot; href=&quot;#DEPOURVUDINTELLIGENCE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;D&#233;pourvu d’intelligence.&lt;/b&gt; L’arm&#233;e ne rate jamais ses tests de &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#MORAL&quot; title=&quot;Le combat de masse&quot;&gt;moral&lt;/a&gt; mais elle est limit&#233;e aux &lt;a class=&quot;pagelink&quot; href=&quot;Tactiques-Des-Arm&#233;es-(Guerre).html#STANDARD&quot; title=&quot;Les tactiques des arm&#233;es&quot;&gt;tactiques&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Phases-Dune-Bataille-(Guerre).html#L&#233;chelle_de_strat&#233;gie_0&quot; title=&quot;Les phases d&amp;#39;une bataille&quot;&gt;strat&#233;gies standards&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;EIDOLON&quot; href=&quot;#EIDOLON&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Eidolon (&lt;a class=&quot;pagelink&quot; href=&quot;Conjurateur.html&quot; title=&quot;Le conjurateur (aussi appel&#233; invocateur)&quot;&gt;conjurateur&lt;/a&gt; 1).&lt;/b&gt; Ce pouvoir fonctionne comme celui de &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#COMPAGNONANIMAL&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;compagnon animal&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;ENNEMIJURE&quot; href=&quot;#ENNEMIJURE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Ennemi jur&#233; (&lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html&quot; title=&quot;Le r&#244;deur&quot;&gt;r&#244;deur&lt;/a&gt; 1).&lt;/b&gt; L’arm&#233;e augmente son &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#MA&quot; title=&quot;Le combat de masse&quot;&gt;MA&lt;/a&gt; de 1 contre un type de cr&#233;ature choisi dans la liste des &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html#ENNEMIJURE&quot; title=&quot;Le r&#244;deur&quot;&gt;ennemis jur&#233;s&lt;/a&gt; du r&#244;deur.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;ENVIRONNEMENTDEPREDILECTION&quot; href=&quot;#ENVIRONNEMENTDEPREDILECTION&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Environnement de pr&#233;dilection (&lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html&quot; title=&quot;Le r&#244;deur&quot;&gt;r&#244;deur&lt;/a&gt; 3).&lt;/b&gt; R&#233;duit de moiti&#233; les bonus ennemis li&#233;s au &lt;a class=&quot;pagelink&quot; href=&quot;Phases-Dune-Bataille-(Guerre).html#CONDITIONS&quot; title=&quot;Les phases d&amp;#39;une bataille&quot;&gt;terrain avantageux&lt;/a&gt; et &#224; l’&lt;a class=&quot;pagelink&quot; href=&quot;Phases-Dune-Bataille-(Guerre).html#CONDITIONS&quot; title=&quot;Les phases d&amp;#39;une bataille&quot;&gt;avantage du terrain&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;ENTRA&#238;NEMENTAUXARMURES&quot; href=&quot;#ENTRA&#238;NEMENTAUXARMURES&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Entra&#238;nement aux armures (&lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html&quot; title=&quot;Le guerrier&quot;&gt;guerrier&lt;/a&gt; 3).&lt;/b&gt; Ce pouvoir de classe modifie la vitesse de base des unit&#233;s qui portent une armure interm&#233;diaire. Modifiez la &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#VITESSE&quot; title=&quot;Le combat de masse&quot;&gt;vitesse&lt;/a&gt; de l’arm&#233;e en cons&#233;quence.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;ESCALADE&quot; href=&quot;#ESCALADE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Escalade.&lt;/b&gt; L’arm&#233;e consid&#232;re que la &lt;a class=&quot;pagelink&quot; href=&quot;Communaut&#233;s-Et-Quartiers.html#DEFENSE&quot; title=&quot;Les communaut&#233;s et les quartiers&quot;&gt;D&#233;fense&lt;/a&gt; des fortifications est r&#233;duite de 25%. Cet avantage ne s’applique pas s’il est &#233;vident que l’on ne peut pas escalader la fortification (s’il s’agit d’une &lt;a class=&quot;pagelink&quot; href=&quot;Communaut&#233;s-Et-Quartiers.html#DOUVE&quot; title=&quot;Les communaut&#233;s et les quartiers&quot;&gt;douve&lt;/a&gt; ou d’un &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mur-De-Force.html&quot; title=&quot;Mur de force&quot;&gt;mur de force&lt;/a&gt;&lt;/i&gt; par exemple).&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;ESQUIVETOTALE&quot; href=&quot;#ESQUIVETOTALE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Esquive totale (&lt;a class=&quot;pagelink&quot; href=&quot;Moine.html&quot; title=&quot;Le moine&quot;&gt;moine&lt;/a&gt; 2, &lt;a class=&quot;pagelink&quot; href=&quot;Roublard.html&quot; title=&quot;Le roublard&quot;&gt;roublard&lt;/a&gt; 2).&lt;/b&gt; Toute arm&#233;e qui attaque celle-ci r&#233;duit de moiti&#233; son &#233;ventuel bonus au &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#MA&quot; title=&quot;Le combat de masse&quot;&gt;MA&lt;/a&gt; li&#233; aux &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#INCANTATION&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;incantations&lt;/a&gt; et r&#233;duit de moiti&#233; les d&#233;g&#226;ts suppl&#233;mentaires de son &#233;ventuelle attaque de &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#SOUFFLE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;souffle&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;ETREINTE&quot; href=&quot;#ETREINTE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;&#201;treinte.&lt;/b&gt; Les unit&#233;s de l’arm&#233;e s’accrochent &#224; leurs adversaires et les emp&#234;chent de fuir. L’arm&#233;e adverse subit un malus de –2 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#MORAL&quot; title=&quot;Le combat de masse&quot;&gt;moral&lt;/a&gt; pour r&#233;sister &#224; une d&#233;route ou pour utiliser la tactique &lt;a class=&quot;pagelink&quot; href=&quot;Tactiques-Des-Arm&#233;es-(Guerre).html#BATTREENRETRAITE&quot; title=&quot;Les tactiques des arm&#233;es&quot;&gt;battre en retraite&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;EVENTRATION&quot; href=&quot;#EVENTRATION&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;&#201;ventration.&lt;/b&gt; L’arm&#233;e augmente ses &lt;a class=&quot;pagelink&quot; href=&quot;Phases-Dune-Bataille-(Guerre).html#TESTDATTAQUE&quot; title=&quot;Les phases d&amp;#39;une bataille&quot;&gt;d&#233;g&#226;ts&lt;/a&gt; de 1.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;FEROCITE&quot; href=&quot;#FEROCITE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;F&#233;rocit&#233;.&lt;/b&gt; L’arm&#233;e continue de se battre, m&#234;me si elle est d&#233;moralis&#233;e ou &#224; l’agonie. Si elle est &lt;a class=&quot;pagelink&quot; href=&quot;Victoire-D&#233;route-Et-D&#233;faite-(Guerre).html&quot; title=&quot;Victoire, d&#233;route et d&#233;faite&quot;&gt;vaincue&lt;/a&gt; ou mise en &lt;a class=&quot;pagelink&quot; href=&quot;Victoire-D&#233;route-Et-D&#233;faite-(Guerre).html&quot; title=&quot;Victoire, d&#233;route et d&#233;faite&quot;&gt;d&#233;route&lt;/a&gt;, elle peut agir pendant une phase de corps &#224; corps de plus mais son &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#MA&quot; title=&quot;Le combat de masse&quot;&gt;MA&lt;/a&gt; et sa &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#VDEF&quot; title=&quot;Le combat de masse&quot;&gt;VD&#233;f&lt;/a&gt; sont r&#233;duits de 4.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;FORMEANIMALE&quot; href=&quot;#FORMEANIMALE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Forme animale (&lt;a class=&quot;pagelink&quot; href=&quot;Druide.html&quot; title=&quot;Le druide&quot;&gt;druide&lt;/a&gt; 4).&lt;/b&gt; Une fois par combat, l’arm&#233;e peut gagner un pouvoir sp&#233;cial : &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#AQUATIQUE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;aquatique&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#AMPHIBIE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;amphibie&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#ESCALADE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;escalade&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#VISIONDANSLENOIR&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;vision dans le noir&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#VOL&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;vol&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#VISIONNOCTURNE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;vision nocturne&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#ODORAT&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;odorat&lt;/a&gt;. Elle perd le pouvoir &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#INCANTATION&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;incantation&lt;/a&gt; tant qu’elle b&#233;n&#233;ficie de l’autre. Elle peut annuler son nouveau pouvoir lors d’une phase ult&#233;rieure.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;GRACE&quot; href=&quot;#GRACE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Gr&#226;ce (&lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html&quot; title=&quot;Le paladin&quot;&gt;paladin&lt;/a&gt; 3).&lt;/b&gt; Apr&#232;s une bataille, l’arm&#233;e peut soigner une &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#MALADIE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;maladie&lt;/a&gt; qui affecte une arm&#233;e alli&#233;e.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;GUERISONACCELEREE&quot; href=&quot;#GUERISONACCELEREE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Gu&#233;rison acc&#233;l&#233;r&#233;e.&lt;/b&gt; Lors de chaque phase &#224; distance ou au corps &#224; corps, cette arm&#233;e r&#233;cup&#232;re un nombre de &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#PV&quot; title=&quot;Le combat de masse&quot;&gt;points de vie&lt;/a&gt; &#233;gal &#224; la moiti&#233; de sa valeur de gu&#233;rison acc&#233;l&#233;r&#233;e. D&#232;s qu’elle cesse de se battre, elle r&#233;cup&#232;re toutes les heures un montant de pv &#233;gal &#224; sa valeur de gu&#233;rison acc&#233;l&#233;r&#233;e.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;IMMUNITE&quot; href=&quot;#IMMUNITE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Immunit&#233;.&lt;/b&gt; Si une arm&#233;e est immunis&#233;e contre un pouvoir sp&#233;cial (comme le &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#POISON&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;poison&lt;/a&gt;), une arm&#233;e ennemie qui dispose de ce pouvoir ne b&#233;n&#233;ficie pas des bonus associ&#233;s quand elle se bat contre elle. Si une arm&#233;e est immunis&#233;e contre beaucoup de choses, consultez &#171; &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#DEFENSEIMPORTANTE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;d&#233;fense importante&lt;/a&gt;. &#187;&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;IMPOSITIONDESMAINS&quot; href=&quot;#IMPOSITIONDESMAINS&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Imposition des mains (&lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html&quot; title=&quot;Le paladin&quot;&gt;paladin&lt;/a&gt; 2).&lt;/b&gt; Ce pouvoir fonctionne comme la &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#CANALISATIONDENERGIEPOSITIVE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;canalisation d’&#233;nergie positive&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;INCANTATION&quot; href=&quot;#INCANTATION&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Incantation.&lt;/b&gt; Si les unit&#233;s d’une arm&#233;e sont capables de lancer des sorts (soit gr&#226;ce &#224; des pouvoirs magiques, soit avec des incantations), augmentez son &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#MA&quot; title=&quot;Le combat de masse&quot;&gt;MA&lt;/a&gt; et sa &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#VDEF&quot; title=&quot;Le combat de masse&quot;&gt;VD&#233;f&lt;/a&gt; d’un chiffre &#233;gal au sort de plus haut niveau qu’elles peuvent lancer. Si un des sorts de l’arm&#233;e a une port&#233;e sup&#233;rieure &#224; contact, cette arm&#233;e peut faire des attaques &#224; distance.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;INSPIRATIONVAILLANTE&quot; href=&quot;#INSPIRATIONVAILLANTE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Inspiration vaillante (&lt;a class=&quot;pagelink&quot; href=&quot;Barde.html&quot; title=&quot;Le barde&quot;&gt;barde&lt;/a&gt; 1).&lt;/b&gt; L’arm&#233;e augmente son &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#MA&quot; title=&quot;Le combat de masse&quot;&gt;MA&lt;/a&gt; de 1 et gagne un bonus de &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#MORAL&quot; title=&quot;Le combat de masse&quot;&gt;moral&lt;/a&gt; de +2 aux tests contre la &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#TERREUR&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;terreur&lt;/a&gt; et la &lt;a class=&quot;pagelink&quot; href=&quot;Victoire-D&#233;route-Et-D&#233;faite-(Guerre).html&quot; title=&quot;Victoire, d&#233;route et d&#233;faite&quot;&gt;d&#233;route&lt;/a&gt;. Elle peut aussi donner ces bonus &#224; une arm&#233;e alli&#233;e qui combat lors de la m&#234;me bataille.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;INTANGIBLE&quot; href=&quot;#INTANGIBLE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Intangible.&lt;/b&gt; L’arm&#233;e ne subit pas de d&#233;g&#226;ts de la part des attaques non magiques et seulement la moiti&#233; de la part des attaques magiques. Elle ignore les bonus ennemis de VD&#233;f]] li&#233;s &#224; des ressources &lt;a class=&quot;pagelink&quot; href=&quot;Ressources-Des-Arm&#233;es-(Guerre).html&quot; title=&quot;Les ressources des arm&#233;es&quot;&gt;d’armure&lt;/a&gt; et r&#233;ussit automatiquement ses tests pour &lt;a class=&quot;pagelink&quot; href=&quot;Tactiques-Des-Arm&#233;es-(Guerre).html#BATTREENRETRAITE&quot; title=&quot;Les tactiques des arm&#233;es&quot;&gt;battre en retraite&lt;/a&gt;. Elle dispose de &lt;a class=&quot;pagelink&quot; href=&quot;Phases-Dune-Bataille-(Guerre).html#CONDITIONS&quot; title=&quot;Les phases d&amp;#39;une bataille&quot;&gt;mobilit&#233; avantageuse&lt;/a&gt; quel que soit le type de terrain.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;/td&gt;&lt;td width=&quot;2%&quot;&gt;
&lt;/td&gt;&lt;td width=&quot;49%&quot;&gt;
&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;INVISIBILITE&quot; href=&quot;#INVISIBILITE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Invisibilit&#233;.&lt;/b&gt; Si une arm&#233;e attaque l’arm&#233;e invisible, elle subit un malus de –2 au &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#MA&quot; title=&quot;Le combat de masse&quot;&gt;MA&lt;/a&gt; pour cette attaque. Si elle se fait attaquer par l’arm&#233;e invisible, elle subit un malus de –2 &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#VDEF&quot; title=&quot;Le combat de masse&quot;&gt;VD&#233;f&lt;/a&gt; contre cette attaque. Les arm&#233;es incapables de voir l’invisible ne peuvent pas emp&#234;cher l’arm&#233;e invisible de &lt;a class=&quot;pagelink&quot; href=&quot;Tactiques-Des-Arm&#233;es-(Guerre).html#BATTREENRETRAITE&quot; title=&quot;Les tactiques des arm&#233;es&quot;&gt;battre en retraite&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;JUGEMENT&quot; href=&quot;#JUGEMENT&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Jugement (&lt;a class=&quot;pagelink&quot; href=&quot;Inquisiteur.html&quot; title=&quot;L&amp;#39;inquisiteur&quot;&gt;inquisiteur&lt;/a&gt; 1).&lt;/b&gt; &#192; chaque phase &#224; distance ou au corps &#224; corps, l’arm&#233;e peut choisir d’augmenter ses &lt;a class=&quot;pagelink&quot; href=&quot;Phases-Dune-Bataille-(Guerre).html#TESTDATTAQUE&quot; title=&quot;Les phases d&amp;#39;une bataille&quot;&gt;d&#233;g&#226;ts&lt;/a&gt; de 1, d’augmenter sa &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#VDEF&quot; title=&quot;Le combat de masse&quot;&gt;VD&#233;f&lt;/a&gt; de 1, de gu&#233;rir d’un nombre de &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#PV&quot; title=&quot;Le combat de masse&quot;&gt;pv&lt;/a&gt; &#233;gal &#224; la moiti&#233; de son &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#FPA&quot; title=&quot;Le combat de masse&quot;&gt;FPA&lt;/a&gt; ou de consid&#233;rer ses attaques comme magiques. Ce pouvoir ne s’applique pas lors des phases o&#249; l’arm&#233;e ne peut pas attaquer parce qu’elle est sous un effet de &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#TERREUR&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;terreur&lt;/a&gt; et se termine si elle est mise en d&#233;route.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;LANCERDEROCHERS&quot; href=&quot;#LANCERDEROCHERS&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Lancer de rochers.&lt;/b&gt; L’arm&#233;e peut faire des attaques &#224; distance. Lors de la phase &#224; distance, elle inflige +4 points de &lt;a class=&quot;pagelink&quot; href=&quot;Phases-Dune-Bataille-(Guerre).html#TESTDATTAQUE&quot; title=&quot;Les phases d&amp;#39;une bataille&quot;&gt;d&#233;g&#226;ts&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;MALADIE&quot; href=&quot;#MALADIE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Maladie.&lt;/b&gt; Si l’arm&#233;e blesse un ennemi, ce dernier tombe malade. Chaque jour suivant la bataille, il subit un malus cumulatif de –1 au &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#MA&quot; title=&quot;Le combat de masse&quot;&gt;MA&lt;/a&gt; et &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#VDEF&quot; title=&quot;Le combat de masse&quot;&gt;VD&#233;f&lt;/a&gt;. Pour soigner la maladie, il faut r&#233;ussir un test de &lt;a class=&quot;pagelink&quot; href=&quot;Royaumes-Et-Guerre.html#STABILITE&quot; title=&quot;Les royaumes et la guerre&quot;&gt;Stabilit&#233;&lt;/a&gt; modifi&#233; par le malus subi. L’arm&#233;e r&#233;duit alors son malus de 1 par jour, jusqu’&#224; ce qu’il ait disparu.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;MALEFICE&quot; href=&quot;#MALEFICE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Mal&#233;fice (&lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re.html&quot; title=&quot;La sorci&#232;re&quot;&gt;sorci&#232;re&lt;/a&gt; 1).&lt;/b&gt; Quand vous cr&#233;ez une arm&#233;e dot&#233;e de ce pouvoir, vous devez choisir entre gu&#233;rison et chaudron.&lt;ul&gt;&lt;li&gt;&lt;i&gt;Gu&#233;rison.&lt;/i&gt; Une fois par bataille, l’arm&#233;e peut gu&#233;rir d’un nombre de &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#PV&quot; title=&quot;Le combat de masse&quot;&gt;points de vie&lt;/a&gt; &#233;gal &#224; la moiti&#233; de son &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#FPA&quot; title=&quot;Le combat de masse&quot;&gt;FPA&lt;/a&gt;.&lt;/li&gt;&lt;li&gt;&lt;i&gt;Chaudron.&lt;/i&gt; L’arm&#233;e peut fabriquer des &lt;a class=&quot;pagelink&quot; href=&quot;Ressources-Des-Arm&#233;es-(Guerre).html#POTIONSDESOINS&quot; title=&quot;Les ressources des arm&#233;es&quot;&gt;potions de soins&lt;/a&gt; (pour elle ou pour une autre arm&#233;e), m&#234;me si elle ne dispose pas des b&#226;timents qui figurent dans les conditions requises de la ressource potions de soins. Vous devez tout de m&#234;me payer leur co&#251;t en &lt;a class=&quot;pagelink&quot; href=&quot;Royaumes-Et-Guerre.html#POINTSDECONSTRUCTION&quot; title=&quot;Les royaumes et la guerre&quot;&gt;PC&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;MOBILITE&quot; href=&quot;#MOBILITE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Mobilit&#233;.&lt;/b&gt; Si les unit&#233;s poss&#232;dent un mode de d&#233;placement qui leur conf&#232;re un avantage sur le champ de bataille (comme des &lt;a class=&quot;pagelink&quot; href=&quot;Bourbi&#233;rin.html&quot; title=&quot;Bourbi&#233;rin&quot;&gt;bourbi&#233;rins&lt;/a&gt; dans un marais), augmentez le &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#MA&quot; title=&quot;Le combat de masse&quot;&gt;MA&lt;/a&gt; de l’arm&#233;e de 1 si elle affronte une arm&#233;e qui ne dispose pas d’une telle mobilit&#233;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;MONTURE&quot; href=&quot;#MONTURE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Monture (&lt;a class=&quot;pagelink&quot; href=&quot;Chevalier.html&quot; title=&quot;Le chevalier&quot;&gt;chevalier&lt;/a&gt; 1).&lt;/b&gt; Les montures de l’arm&#233;e augmentent le &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#MA&quot; title=&quot;Le combat de masse&quot;&gt;MA&lt;/a&gt; et la &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#VDEF&quot; title=&quot;Le combat de masse&quot;&gt;VD&#233;f&lt;/a&gt; de 1.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;MORTVIVANT&quot; href=&quot;#MORTVIVANT&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Mort-vivant.&lt;/b&gt; L’arm&#233;e est immunis&#233;e contre la &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#MALADIE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;maladie&lt;/a&gt;, la &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#TERREUR&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;terreur&lt;/a&gt;, la &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#PARALYSIE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;paralysie&lt;/a&gt; et le &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#POISON&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;poison&lt;/a&gt;. Sa &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#VDEF&quot; title=&quot;Le combat de masse&quot;&gt;VD&#233;f&lt;/a&gt; augmente de 2.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;NAGEDANSLATERRE&quot; href=&quot;#NAGEDANSLATERRE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Nage dans la terre.&lt;/b&gt; L’arm&#233;e ignore les fortifications faites de terre ou de pierre et peut creuser sous les autres comme si elle poss&#233;dait le pouvoir &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#CREUSEMENT&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;creusement&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;NUEE&quot; href=&quot;#NUEE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Nu&#233;e.&lt;/b&gt; L’arm&#233;e subit des d&#233;g&#226;ts r&#233;duits de moiti&#233; de la part des attaques non magiques mais les attaques magiques lui infligent 1,5 fois plus de d&#233;g&#226;ts que la normale. L’arm&#233;e ignore les bonus de &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#VDEF&quot; title=&quot;Le combat de masse&quot;&gt;VD&#233;f&lt;/a&gt; li&#233;s aux armures. Elle ne peut pas blesser une arm&#233;e &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#INTANGIBLE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;intangible&lt;/a&gt; ou dot&#233;e d’une &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#DEFENSEIMPORTANTE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;d&#233;fense importante&lt;/a&gt;. Elle r&#233;ussit automatiquement ses tests pour &lt;a class=&quot;pagelink&quot; href=&quot;Tactiques-Des-Arm&#233;es-(Guerre).html#BATTREENRETRAITE&quot; title=&quot;Les tactiques des arm&#233;es&quot;&gt;battre en retraite&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;ODORAT&quot; href=&quot;#ODORAT&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Odorat.&lt;/b&gt; L’arm&#233;e r&#233;duit ses malus de &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#MA&quot; title=&quot;Le combat de masse&quot;&gt;MA&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#VDEF&quot; title=&quot;Le combat de masse&quot;&gt;VD&#233;f&lt;/a&gt; de moiti&#233; dans les t&#233;n&#232;bres ainsi qu’en cas d’&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#INVISIBILITE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;invisibilit&#233;&lt;/a&gt; ennemie ou de m&#233;t&#233;o d&#233;favorable.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;ORDRE&quot; href=&quot;#ORDRE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Ordre (&lt;a class=&quot;pagelink&quot; href=&quot;Chevalier.html&quot; title=&quot;Le chevalier&quot;&gt;chevalier&lt;/a&gt; 1).&lt;/b&gt; Quand l’arm&#233;e utilise le pouvoir de &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#DEFI&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;d&#233;fi&lt;/a&gt;, elle augmente sa &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#VDEF&quot; title=&quot;Le combat de masse&quot;&gt;VD&#233;f&lt;/a&gt; de 1 contre l’arm&#233;e qu’elle d&#233;fie.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;PACTEDUCHASSEUR&quot; href=&quot;#PACTEDUCHASSEUR&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Pacte du chasseur (&lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html&quot; title=&quot;Le r&#244;deur&quot;&gt;r&#244;deur&lt;/a&gt; 4).&lt;/b&gt; Quand vous cr&#233;ez une arm&#233;e dot&#233;e de ce pouvoir, choisissez entre compagnons ou animal.&lt;ul&gt;&lt;li&gt;&lt;i&gt;Compagnons.&lt;/i&gt; Une fois par bataille, l’arm&#233;e augmente son &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#MA&quot; title=&quot;Le combat de masse&quot;&gt;MA&lt;/a&gt; ou celui d’une arm&#233;e alli&#233;e de 1 pour le reste de l’affrontement.&lt;/li&gt;&lt;li&gt;&lt;i&gt;Animal.&lt;/i&gt; Ce pouvoir fonctionne comme celui de &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#COMPAGNONANIMAL&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;compagnon animal&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;PARALYSIE&quot; href=&quot;#PARALYSIE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Paralysie.&lt;/b&gt; &#192; chaque fois que l’arm&#233;e blesse une arm&#233;e ennemie, cette derni&#232;re voit sa &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#VDEF&quot; title=&quot;Le combat de masse&quot;&gt;VD&#233;f&lt;/a&gt; diminuer de 1.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;PATTESARRIERES&quot; href=&quot;#PATTESARRIERES&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Pattes arri&#232;res.&lt;/b&gt; Les &lt;a class=&quot;pagelink&quot; href=&quot;Phases-Dune-Bataille-(Guerre).html#TESTDATTAQUE&quot; title=&quot;Les phases d&amp;#39;une bataille&quot;&gt;d&#233;g&#226;ts&lt;/a&gt; de l’arm&#233;e augmentent de 1.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;PERCEPTIONAVEUGLE&quot; href=&quot;#PERCEPTIONAVEUGLE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Perception aveugle.&lt;/b&gt; Dans les &lt;a class=&quot;pagelink&quot; href=&quot;Phases-Dune-Bataille-(Guerre).html#CONDITIONS&quot; title=&quot;Les phases d&amp;#39;une bataille&quot;&gt;t&#233;n&#232;bres&lt;/a&gt;, par mauvais temps ou face &#224; une arm&#233;e &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#INVISIBILITE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;invisible&lt;/a&gt;, l’arm&#233;e r&#233;duit ses malus au &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#MA&quot; title=&quot;Le combat de masse&quot;&gt;MA&lt;/a&gt; et &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#VDEF&quot; title=&quot;Le combat de masse&quot;&gt;VD&#233;f&lt;/a&gt; de moiti&#233;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;PERCEPTIONDESVIBRATIONS&quot; href=&quot;#PERCEPTIONDESVIBRATIONS&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Perception des vibrations.&lt;/b&gt; L’arm&#233;e r&#233;duit de moiti&#233; ses malus au &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#MA&quot; title=&quot;Le combat de masse&quot;&gt;MA&lt;/a&gt; et &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#VDEF&quot; title=&quot;Le combat de masse&quot;&gt;VD&#233;f&lt;/a&gt; dans les &lt;a class=&quot;pagelink&quot; href=&quot;Phases-Dune-Bataille-(Guerre).html#CONDITIONS&quot; title=&quot;Les phases d&amp;#39;une bataille&quot;&gt;t&#233;n&#232;bres&lt;/a&gt; ou en cas d’&lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#INVISIBILITE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;invisibilit&#233;&lt;/a&gt; ennemie ou de m&#233;t&#233;o d&#233;favorable.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;PETRIFICATION&quot; href=&quot;#PETRIFICATION&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;P&#233;trification.&lt;/b&gt; Ce pouvoir fonctionne comme &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#PARALYSIE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;paralysie&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;PISTAGE&quot; href=&quot;#PISTAGE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Pistage (&lt;a class=&quot;pagelink&quot; href=&quot;Inquisiteur.html&quot; title=&quot;L&amp;#39;inquisiteur&quot;&gt;inquisiteur&lt;/a&gt; 2, &lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html&quot; title=&quot;Le r&#244;deur&quot;&gt;r&#244;deur&lt;/a&gt; 1).&lt;/b&gt; L’arm&#233;e ajoute son &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#FPA&quot; title=&quot;Le combat de masse&quot;&gt;FPA&lt;/a&gt; aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#MORAL&quot; title=&quot;Le combat de masse&quot;&gt;moral&lt;/a&gt; pour emp&#234;cher une arm&#233;e d’utiliser la tactique &lt;a class=&quot;pagelink&quot; href=&quot;Tactiques-Des-Arm&#233;es-(Guerre).html#BATTREENRETRAITE&quot; title=&quot;Les tactiques des arm&#233;es&quot;&gt;battre en retraite&lt;/a&gt; et &#224; sa &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#VDEF&quot; title=&quot;Le combat de masse&quot;&gt;VD&#233;f&lt;/a&gt; pour &#233;viter de tomber dans une &lt;a class=&quot;pagelink&quot; href=&quot;Tactiques-Des-Arm&#233;es-(Guerre).html#EMBUSCADE&quot; title=&quot;Les tactiques des arm&#233;es&quot;&gt;embuscade&lt;/a&gt;. En cas de &lt;a class=&quot;pagelink&quot; href=&quot;Phases-Dune-Bataille-(Guerre).html#CONDITIONS&quot; title=&quot;Les phases d&amp;#39;une bataille&quot;&gt;brouillard&lt;/a&gt;, ses d&#233;g&#226;ts sont r&#233;duits d’un quart et non de moiti&#233;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;PIETINEMENT&quot; href=&quot;#PIETINEMENT&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Pi&#233;tinement.&lt;/b&gt; L’arm&#233;e augmente son &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#MA&quot; title=&quot;Le combat de masse&quot;&gt;MA&lt;/a&gt; de 1.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;POISON&quot; href=&quot;#POISON&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Poison.&lt;/b&gt; Ce pouvoir fonctionne comme &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#SAIGNEMENT&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;saignement&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;PREPARATIONDEPOTION&quot; href=&quot;#PREPARATIONDEPOTION&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Pr&#233;paration de potion (&lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;alchimiste&lt;/a&gt; 1).&lt;/b&gt; L’arm&#233;e peut cr&#233;er des &lt;a class=&quot;pagelink&quot; href=&quot;Ressources-Des-Arm&#233;es-(Guerre).html#POTIONSDESOINS&quot; title=&quot;Les ressources des arm&#233;es&quot;&gt;potions de soins&lt;/a&gt;, pour elle ou pour une autre arm&#233;e, m&#234;me si elle ne dispose pas des b&#226;timents qui figurent dans les conditions requises de la ressource potions de soins. Vous devez tout de m&#234;me payer leur co&#251;t en &lt;a class=&quot;pagelink&quot; href=&quot;Royaumes-Et-Guerre.html#POINTSDECONSTRUCTION&quot; title=&quot;Les royaumes et la guerre&quot;&gt;PC&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;PROTECTIONDALLIE&quot; href=&quot;#PROTECTIONDALLIE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Protection d’alli&#233; (&lt;a class=&quot;pagelink&quot; href=&quot;Conjurateur.html&quot; title=&quot;Le conjurateur (aussi appel&#233; invocateur)&quot;&gt;conjurateur&lt;/a&gt; 4).&lt;/b&gt; La &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#VDEF&quot; title=&quot;Le combat de masse&quot;&gt;VD&#233;f&lt;/a&gt; de l’arm&#233;e augmente de 1.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;RAGE&quot; href=&quot;#RAGE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Rage (&lt;a class=&quot;pagelink&quot; href=&quot;Barbare.html&quot; title=&quot;Le barbare&quot;&gt;barbare&lt;/a&gt; 1).&lt;/b&gt; Une fois par bataille, le &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#COMMANDANT&quot; title=&quot;Le combat de masse&quot;&gt;commandant&lt;/a&gt; peut ordonner &#224; son arm&#233;e d’entrer en rage. Augmentez le &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#MA&quot; title=&quot;Le combat de masse&quot;&gt;MA&lt;/a&gt; de l’arm&#233;e de 2, r&#233;duisez sa &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#VDEF&quot; title=&quot;Le combat de masse&quot;&gt;VD&#233;f&lt;/a&gt; de 1 et ajoutez-lui un bonus de +1 aux tests de &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#MORAL&quot; title=&quot;Le combat de masse&quot;&gt;moral&lt;/a&gt; contre la &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#TERREUR&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;terreur&lt;/a&gt; et la &lt;a class=&quot;pagelink&quot; href=&quot;Victoire-D&#233;route-Et-D&#233;faite-(Guerre).html&quot; title=&quot;Victoire, d&#233;route et d&#233;faite&quot;&gt;d&#233;route&lt;/a&gt;. Tant que l’arm&#233;e est sous cet effet, elle n’a plus acc&#232;s aux tactiques &lt;a class=&quot;pagelink&quot; href=&quot;Tactiques-Des-Arm&#233;es-(Guerre).html#COMBATPRUDENT&quot; title=&quot;Les tactiques des arm&#233;es&quot;&gt;combat prudent&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Tactiques-Des-Arm&#233;es-(Guerre).html#MURPROTECTEUR&quot; title=&quot;Les tactiques des arm&#233;es&quot;&gt;mur protecteur&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Tactiques-Des-Arm&#233;es-(Guerre).html#SPECIALISTESDELENCERCLEMENT&quot; title=&quot;Les tactiques des arm&#233;es&quot;&gt;sp&#233;cialistes de l’encerclement&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Tactiques-Des-Arm&#233;es-(Guerre).html#TENIRLALIGNE&quot; title=&quot;Les tactiques des arm&#233;es&quot;&gt;tenir la ligne&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Tactiques-Des-Arm&#233;es-(Guerre).html#SNIPERSENSOUTIEN&quot; title=&quot;Les tactiques des arm&#233;es&quot;&gt;snipers en soutien&lt;/a&gt; ou &lt;a class=&quot;pagelink&quot; href=&quot;Tactiques-Des-Arm&#233;es-(Guerre).html#BATTREENRETRAITE&quot; title=&quot;Les tactiques des arm&#233;es&quot;&gt;battre en retraite&lt;/a&gt;. Elle est aussi priv&#233;e des &lt;a class=&quot;pagelink&quot; href=&quot;Phases-Dune-Bataille-(Guerre).html#L&#233;chelle_de_strat&#233;gie_0&quot; title=&quot;Les phases d&amp;#39;une bataille&quot;&gt;strat&#233;gies&lt;/a&gt; d&#233;fensive et prudente. Si elle utilisait une strat&#233;gie ou une tactique prohib&#233;e, elle opte de suite pour la version standard.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;RECEPTIONDEROCHERS&quot; href=&quot;#RECEPTIONDEROCHERS&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;R&#233;ception de rochers.&lt;/b&gt; La &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#VDEF&quot; title=&quot;Le combat de masse&quot;&gt;VD&#233;f&lt;/a&gt; de l’arm&#233;e augmente de 1 contre les attaques &#224; distance. Elle augmente d’encore 1 point si son adversaire l’attaque avec des &lt;a class=&quot;pagelink&quot; href=&quot;Ressources-Des-Arm&#233;es-(Guerre).html#ENGINSDESIEGE&quot; title=&quot;Les ressources des arm&#233;es&quot;&gt;armes de si&#232;ge&lt;/a&gt; ou lui &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#LANCERDEROCHERS&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;lance des rochers&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;REDUCTIONDEDEGATS&quot; href=&quot;#REDUCTIONDEDEGATS&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;R&#233;duction de d&#233;g&#226;ts.&lt;/b&gt; Voir &#171; &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#DEFENSEIMPORTANTE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;d&#233;fense importante&lt;/a&gt;. &#187;&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;REGENERATION&quot; href=&quot;#REGENERATION&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;R&#233;g&#233;n&#233;ration.&lt;/b&gt; &#192; chaque phase &#224; distance ou au corps &#224; corps, l’arm&#233;e r&#233;cup&#232;re un montant de &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#PV&quot; title=&quot;Le combat de masse&quot;&gt;points de vie&lt;/a&gt; &#233;gal &#224; la moiti&#233; de sa r&#233;g&#233;n&#233;ration. Quand une arm&#233;e dot&#233;e d’un pouvoir de r&#233;g&#233;n&#233;ration tombe &#224; 0 pv, elle est vaincue seulement s’il reste une arm&#233;e adverse en vie, afin d’achever les cr&#233;atures en train de se r&#233;g&#233;n&#233;rer. En dehors des combats, l’arm&#233;e r&#233;cup&#232;re toutes les heures un montant de points de vie &#233;gal &#224; la moiti&#233; de sa valeur de r&#233;g&#233;n&#233;ration.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;RESERVEDEKI&quot; href=&quot;#RESERVEDEKI&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;R&#233;serve de ki (&lt;a class=&quot;pagelink&quot; href=&quot;Moine.html&quot; title=&quot;Le moine&quot;&gt;moine&lt;/a&gt; 4).&lt;/b&gt; Les attaques de l’arm&#233;e sont consid&#233;r&#233;es comme magiques.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;RESISTANCE&quot; href=&quot;#RESISTANCE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;R&#233;sistance.&lt;/b&gt; Consultez &#171; &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#DEFENSEIMPORTANTE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;d&#233;fense importante&lt;/a&gt;. &#187;&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;RESISTANCEALAMAGIE&quot; href=&quot;#RESISTANCEALAMAGIE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;R&#233;sistance &#224; la magie.&lt;/b&gt; L’arm&#233;e augmente sa &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#VDEF&quot; title=&quot;Le combat de masse&quot;&gt;VD&#233;f&lt;/a&gt; de 6 contre les arm&#233;es qui poss&#232;dent le pouvoir &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#INCANTATION&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;incantation&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;RESISTANCEAUPOISON&quot; href=&quot;#RESISTANCEAUPOISON&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;R&#233;sistance au poison (&lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;alchimiste&lt;/a&gt; 2).&lt;/b&gt; Si l’arm&#233;e re&#231;oit des d&#233;g&#226;ts de &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#POISON&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;poison&lt;/a&gt;, ils sont r&#233;duits de la moiti&#233; du bonus de r&#233;sistance au poison des unit&#233;s.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;SAIGNEMENT&quot; href=&quot;#SAIGNEMENT&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Saignement.&lt;/b&gt; Quand cette arm&#233;e inflige des d&#233;g&#226;ts de corps &#224; corps, sa cible re&#231;oit automatiquement 1d6 points de d&#233;g&#226;ts au d&#233;but de la phase suivante.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;SANTEDIVINE&quot; href=&quot;#SANTEDIVINE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Sant&#233; divine (&lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html&quot; title=&quot;Le paladin&quot;&gt;paladin&lt;/a&gt; 3).&lt;/b&gt; L’arm&#233;e est immunis&#233;e contre la &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#MALADIE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;maladie&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;SENSDESPIEGES&quot; href=&quot;#SENSDESPIEGES&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Sens des pi&#232;ges (&lt;a class=&quot;pagelink&quot; href=&quot;Roublard.html&quot; title=&quot;Le roublard&quot;&gt;roublard&lt;/a&gt; 3).&lt;/b&gt; Quand l’arm&#233;e utilise la tactique &lt;a class=&quot;pagelink&quot; href=&quot;Tactiques-Des-Arm&#233;es-(Guerre).html#BRISEURDESIEGE&quot; title=&quot;Les tactiques des arm&#233;es&quot;&gt;briseur de si&#232;ge&lt;/a&gt;, elle ajoute la moiti&#233; de son &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#FPA&quot; title=&quot;Le combat de masse&quot;&gt;FPA&lt;/a&gt; &#224; son &lt;a class=&quot;pagelink&quot; href=&quot;Phases-Dune-Bataille-(Guerre).html#TESTDATTAQUE&quot; title=&quot;Les phases d&amp;#39;une bataille&quot;&gt;test d’attaque&lt;/a&gt; pour savoir si elle a d&#233;truit l’engin de si&#232;ge.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;SENSIBILITEALALUMIERE&quot; href=&quot;#SENSIBILITEALALUMIERE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Sensibilit&#233; &#224; la lumi&#232;re.&lt;/b&gt; Le &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#MA&quot; title=&quot;Le combat de masse&quot;&gt;MA&lt;/a&gt; et la &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#VDEF&quot; title=&quot;Le combat de masse&quot;&gt;VD&#233;f&lt;/a&gt; de l’arm&#233;e diminuent de 1 sous une vive lumi&#232;re.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;SOUFFLE&quot; href=&quot;#SOUFFLE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Souffle.&lt;/b&gt; L’arm&#233;e peut faire des attaques &#224; distance. Lors des phases &#224; distance et au corps &#224; corps, elle inflige +1d4 points de d&#233;g&#226;ts.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;SPECIALISATIONMARTIALE&quot; href=&quot;#SPECIALISATIONMARTIALE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Sp&#233;cialisation martiale (&lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html&quot; title=&quot;Le guerrier&quot;&gt;guerrier&lt;/a&gt; 4).&lt;/b&gt; Une fois par bataille, l’arm&#233;e augmente le &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#MA&quot; title=&quot;Le combat de masse&quot;&gt;MA&lt;/a&gt; de ses attaques &#224; distance ou au corps &#224; corps de 2.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;STYLEDECOMBAT&quot; href=&quot;#STYLEDECOMBAT&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Style de combat (&lt;a class=&quot;pagelink&quot; href=&quot;R&#244;deur.html&quot; title=&quot;Le r&#244;deur&quot;&gt;r&#244;deur&lt;/a&gt; 2).&lt;/b&gt; Une fois par bataille, vous pouvez augmenter le &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#MA&quot; title=&quot;Le combat de masse&quot;&gt;MA&lt;/a&gt; de 1 pour les attaques &#224; distance ou au corps &#224; cors et ce pour toute la dur&#233;e de l’affrontement.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;TACTICIEN&quot; href=&quot;#TACTICIEN&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Tacticien (&lt;a class=&quot;pagelink&quot; href=&quot;Chevalier.html&quot; title=&quot;Le chevalier&quot;&gt;chevalier&lt;/a&gt; 1).&lt;/b&gt; L’arm&#233;e apprend automatiquement une tactique (en g&#233;n&#233;ral &lt;a class=&quot;pagelink&quot; href=&quot;Tactiques-Des-Arm&#233;es-(Guerre).html#CAVALIERSEXPERTS&quot; title=&quot;Les tactiques des arm&#233;es&quot;&gt;cavaliers experts&lt;/a&gt;) qui n’est pas d&#233;compt&#233;e du nombre maximal de tactiques qu’elle peut apprendre.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;TALENTDEROUBLARD&quot; href=&quot;#TALENTDEROUBLARD&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Talent de roublard (&lt;a class=&quot;pagelink&quot; href=&quot;Roublard.html&quot; title=&quot;Le roublard&quot;&gt;roublard&lt;/a&gt; 2).&lt;/b&gt; L’arm&#233;e gagne le pouvoir &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#SAIGNEMENT&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;saignement&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;TELEPORTATION&quot; href=&quot;#TELEPORTATION&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;T&#233;l&#233;portation.&lt;/b&gt; L’arm&#233;e ignore la &lt;a class=&quot;pagelink&quot; href=&quot;Communaut&#233;s-Et-Quartiers.html#DEFENSE&quot; title=&quot;Les communaut&#233;s et les quartiers&quot;&gt;D&#233;fense&lt;/a&gt; des fortifications. Elle r&#233;ussit automatiquement ses tests pour &lt;a class=&quot;pagelink&quot; href=&quot;Tactiques-Des-Arm&#233;es-(Guerre).html#BATTREENRETRAITE&quot; title=&quot;Les tactiques des arm&#233;es&quot;&gt;battre en retraite&lt;/a&gt;. Les d&#233;placements dans l’&#233;ther et autres effets similaires donnent le m&#234;me pouvoir. Une arm&#233;e capable de se t&#233;l&#233;porter peut se rendre dans la journ&#233;e dans n’importe quel hexagone (peut importe sa vitesse et la pr&#233;sence &#233;ventuelle de terrain difficile).&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;TERREUR&quot; href=&quot;#TERREUR&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Terreur.&lt;/b&gt; Si l’arm&#233;e blesse une arm&#233;e ennemie, cette derni&#232;re doit faire un test de &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#MORAL&quot; title=&quot;Le combat de masse&quot;&gt;moral&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; = 10 + &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#FPA&quot; title=&quot;Le combat de masse&quot;&gt;FPA&lt;/a&gt; de votre arm&#233;e). En cas d’&#233;chec, elle est effray&#233;e et ne peut pas faire de &lt;a class=&quot;pagelink&quot; href=&quot;Phases-Dune-Bataille-(Guerre).html#TESTDATTAQUE&quot; title=&quot;Les phases d&amp;#39;une bataille&quot;&gt;test d’attaque&lt;/a&gt; lors de la prochaine phase. Si une arm&#233;e rate son test de moral alors qu’elle est d&#233;j&#224; effray&#233;e, elle est en &lt;a class=&quot;pagelink&quot; href=&quot;Victoire-D&#233;route-Et-D&#233;faite-(Guerre).html&quot; title=&quot;Victoire, d&#233;route et d&#233;faite&quot;&gt;d&#233;route&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;TOURBILLON&quot; href=&quot;#TOURBILLON&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Tourbillon.&lt;/b&gt; Ce pouvoir fonctionne comme &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#PARALYSIE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;paralysie&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;VEGETALE&quot; href=&quot;#VEGETALE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;V&#233;g&#233;tale.&lt;/b&gt; L’arm&#233;e est immunis&#233;e contre la &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#TERREUR&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;terreur&lt;/a&gt;, la &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#PARALYSIE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;paralysie&lt;/a&gt; et le &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#POISON&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;poison&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;VISIONDANSLENOIR&quot; href=&quot;#VISIONDANSLENOIR&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Vision dans le noir.&lt;/b&gt; Dans les &lt;a class=&quot;pagelink&quot; href=&quot;Phases-Dune-Bataille-(Guerre).html#CONDITIONS&quot; title=&quot;Les phases d&amp;#39;une bataille&quot;&gt;t&#233;n&#232;bres&lt;/a&gt; ou sous une &lt;a class=&quot;pagelink&quot; href=&quot;Phases-Dune-Bataille-(Guerre).html#CONDITIONS&quot; title=&quot;Les phases d&amp;#39;une bataille&quot;&gt;faible luminosit&#233;&lt;/a&gt;, l’arm&#233;e ne subit aucun malus au &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#MA&quot; title=&quot;Le combat de masse&quot;&gt;MA&lt;/a&gt; ni &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Combat-De-Masse.html#VDEF&quot; title=&quot;Le combat de masse&quot;&gt;VD&#233;f&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;VISIONNOCTURNE&quot; href=&quot;#VISIONNOCTURNE&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Vision nocturne.&lt;/b&gt; L’arm&#233;e ne subit aucun malus en cas de &lt;a class=&quot;pagelink&quot; href=&quot;Phases-Dune-Bataille-(Guerre).html#CONDITIONS&quot; title=&quot;Les phases d&amp;#39;une bataille&quot;&gt;faible luminosit&#233;&lt;/a&gt;.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;VOL&quot; href=&quot;#VOL&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Vol.&lt;/b&gt; Si l’arm&#233;e n’attaque pas lors de la phase de corps &#224; corps, les arm&#233;es adverses ne peuvent pas l’attaquer au corps &#224; corps, sauf si elles volent aussi. L’arm&#233;e ignore les bonus de &lt;a class=&quot;pagelink&quot; href=&quot;Communaut&#233;s-Et-Quartiers.html#DEFENSE&quot; title=&quot;Les communaut&#233;s et les quartiers&quot;&gt;D&#233;fense&lt;/a&gt; des &lt;a class=&quot;pagelink&quot; href=&quot;Communaut&#233;s-Et-Quartiers.html#MURDENCEINTE&quot; title=&quot;Les communaut&#233;s et les quartiers&quot;&gt;murs d’enceinte&lt;/a&gt; mais pas ceux des autres fortifications.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;ul&gt;&lt;li&gt;&lt;div class=&quot;ref right&quot; style=&quot;padding: 0 0 3px 3px;&quot;&gt;&lt;a name=&quot;VORTEX&quot; href=&quot;#VORTEX&quot;&gt;&lt;img class=&quot;opachover&quot; src=&quot;/images/pathfinder/wiki/logoref.png&quot; width=&quot;12px&quot; style=&quot;opacity:0.1&quot;&gt;&lt;/a&gt;&lt;/div&gt;&lt;b&gt;Vortex.&lt;/b&gt; Ce pouvoir fonctionne comme la &lt;a class=&quot;pagelink&quot; href=&quot;Pouvoirs-Sp&#233;ciaux-(Guerre).html#PARALYSIE&quot; title=&quot;Les pouvoirs sp&#233;ciaux&quot;&gt;paralysie&lt;/a&gt; mais uniquement contre des cibles qui se trouvent sur ou dans l’eau.&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
